package com.asmj.marketplace.notification.controller;import com.asmj.marketplace.notification.model.Notification;import com.asmj.marketplace.notification.service.NotificationService;import com.asmj.marketplace.common.response.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/notifications")@RequiredArgsConstructor public class NotificationController{private final NotificationService s;@GetMapping public ApiResponse<List<Notification>> mine(Authentication a){return ApiResponse.ok("Notifications",s.mine(a.getName()));}@PutMapping("/{id}/read")public ApiResponse<Void> read(@PathVariable String id){s.read(id);return ApiResponse.ok("Marked read",null);}}
